/**
 * Recupera las carpetas municipales que faltan en GitHub antes de compilar.
 * Contiene los 102 archivos originales de src/ y public/ comprimidos.
 * No descarga archivos, no requiere dependencias y conserva archivos existentes.
 * Después de ejecutarlo localmente, se pueden subir las carpetas recuperadas y
 * volver al buildCommand normal: npm run build.
 */
import { gunzipSync } from 'node:zlib';
import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
const root = dirname(fileURLToPath(import.meta.url));
const payload = "";
const files = JSON.parse(gunzipSync(Buffer.from(payload, 'base64')).toString('utf8'));
let restored = 0, retained = 0;
for (const entry of files) {
  if (!/^(src|public)\//.test(entry.path)) throw new Error('Ruta ajena al proyecto');
  const target = resolve(root, entry.path);
  if (!target.startsWith(root + sep)) throw new Error('Ruta inválida');
  const bytes = Buffer.from(entry.data, 'base64');
  if (createHash('sha256').update(bytes).digest('hex') !== entry.sha256) {
    throw new Error('No coincide la integridad de ' + entry.path);
  }
  if (existsSync(target)) { retained++; continue; }
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, bytes, { flag: 'wx' });
  restored++;
}
for (const required of ['src/main.tsx', 'public/data/map/seccion.geojson', 'public/data/map/manifest.json']) {
  if (!existsSync(resolve(root, required))) throw new Error('Falta ' + required);
}
console.log(`[Almoloya] Archivos restaurados: ${restored}; archivos existentes conservados: ${retained}.`);
